function showJournal(tab='knowledge',selection=0){
 const items=tab==='knowledge'?state.knowledge:tab==='memories'?state.memories:state.journal;
 const labels=[['knowledge','Informations',state.knowledge.length],['memories','Souvenirs',state.memories.length],['journal','Journal',state.journal.length]],selected=items[Math.min(selection,items.length-1)];
 const body=selected?`<article class="note-reading"><div class="note-dateline"><span>AVRIL / JOUR ${String(selected.day).padStart(2,'0')}</span><span>${esc(tab==='knowledge'?selected.kind:'Notes personnelles')}</span></div><span class="note-number">${String(selection+1).padStart(2,'0')}</span><h3>${esc(tab==='knowledge'?selected.title:tab==='memories'?'Un souvenir à garder.':'Ce que je retiens.')}</h3>${tab==='knowledge'?`<p>Une information à garder en tête pour la suite de la semaine.</p><div class="note-source">${icon('eye')}<span>Source identifiée<b>${esc(selected.source)}</b></span></div>`:`<p>${esc(selected.text)}</p>`}<div class="note-signature">${esc(state.name)}<span>Notes personnelles / ANHS</span></div></article>`:`<article class="note-reading empty-notebook"><span class="note-number">00</span>${icon('book')}<h3>Tout commence<br>par une observation.</h3><p>${tab==='knowledge'?'Les informations recueillies pendant vos conversations apparaîtront ici.':tab==='memories'?'Vos rencontres laisseront bientôt leurs premières traces.':'Votre semaine attend ses premières lignes.'}</p><button class="secondary-btn" data-shell-menu="map">Explorer le campus ${icon('map')}</button></article>`;
 openModal(`${modalHead('GARDER UNE TRACE','Carnet personnel',"Les faits, les rencontres, ce qu’on ne dit pas.")}<div class="tabs notebook-tabs">${labels.map(([id,label,count])=>`<button class="tab-btn ${id===tab?'active':''}" data-journal="${id}">${label}<span>${count}</span></button>`).join('')}</div><div class="notebook-layout"><aside class="note-index"><header>${items.length} entrée${items.length>1?'s':''}<span>AVRIL</span></header>${items.length?items.map((k,i)=>`<button class="${selection===i?'selected':''}" data-note="${i}"><time>JOUR ${String(k.day).padStart(2,'0')}</time><b>${esc(tab==='knowledge'?k.title:k.text)}</b><span>${tab==='knowledge'?esc(k.kind):'Note personnelle'} ↗</span></button>`).join(''):'<p>Aucune entrée pour l’instant.</p>'}</aside>${body}</div>`,'journal-book');
 $$('[data-journal]').forEach(b=>b.onclick=()=>showJournal(b.dataset.journal));$$('[data-note]').forEach(b=>b.onclick=()=>showJournal(tab,Number(b.dataset.note)));
}
function showProfile(){
 const skills=[['academic','Académique','Comprendre et préparer.'],['observation','Observation','Lire entre les lignes.'],['communication','Communication','Trouver les bons mots.'],['composure','Sang-froid','Garder une longueur d’avance.']];
 openModal(`${modalHead('PREMIÈRE ANNÉE / CLASSE D','Mon élève',"Votre place se construit, un choix à la fois.")}<div class="profile-layout"><section class="identity-stage"><span class="identity-watermark" aria-hidden="true">D</span><div class="identity-top"><span>ANHS / DOSSIER PERSONNEL</span><i>01 — D</i></div>${avatar('player','profile-character')}<div class="identity-caption"><span class="identity-archetype">${esc(ARCHETYPES[state.archetype]?.label??'Élève')}</span><h3>${esc(state.name)}</h3><p>${esc(repTitle(state))}</p></div><div class="identity-bottom"><span>CLASSE <b>D</b></span><span>AVRIL / AN 01</span></div></section><div class="profile-abilities"><header class="section-heading"><h3>Compétences</h3><span>01 / POTENTIEL</span></header><div class="ability-list">${skills.map(([id,label,detail],i)=>`<div class="ability"><span class="ability-index">0${i+1}</span><div><header><b>${label}</b><strong>${state.stats[id]}<small>/100</small></strong></header><p>${detail}</p><div class="ability-track"><i style="width:${state.stats[id]}%"></i></div></div></div>`).join('')}</div><div class="profile-partner">${avatar(state.partner??'player')}<div><small>VOTRE BINÔME</small><b>${state.partner?esc(PEOPLE[state.partner].name):'À vous de le choisir'}</b><span>${state.partner?'Inscription au premier examen':'Rencontrez vos camarades sur le campus'}</span></div><button class="partner-link" data-shell-menu="map" aria-label="Ouvrir la carte du campus">↗</button></div></div></div><div class="profile-metrics">${[['Préparation',state.prep,'Points de dossier'],['Soutien',state.support,'Aide à la classe'],['Révisions',state.studyCount,'Séances suivies']].map(([l,v,d])=>`<div><small>${l}</small><b>${v}</b><span>${d}</span></div>`).join('')}</div><header class="section-heading"><h3>Ce que la classe retient</h3><span>02 / RÉPUTATION</span></header>${showRepHelp()}<div class="profile-conditions">${conditions(state).map(c=>`<span>${icon(STATE_ICONS[c.id])}<b>${esc(c.label)}</b>${esc(c.detail)}</span>`).join('')||'<span>Aucun état particulier pour le moment.</span>'}</div>`,'student-profile');
}
function showClass(){const groups=[['A',1200],['B',1000],['C',800],['D',state.pc]];openModal(`${modalHead('ANHS / RÉSULTATS','Classement','Les points de classe déterminent votre position.')}<table class="rank-table"><tbody>${groups.map(([name,pc],i)=>`<tr class="${name==='D'?'you':''}"><td>0${i+1}</td><td>Classe ${name}${name==='D'?' · Votre classe':''}</td><td>${fmt(pc)} PC</td></tr>`).join('')}</tbody></table><div class="hint-box">${state.exam?`Premier examen : ${state.exam.classScore}/100 pour la classe · ${state.exam.reward>0?'+':''}${state.exam.reward} PC.`:'Le contrat de confiance aura lieu vendredi. Un binôme bien préparé compte, une classe bien préparée compte davantage.'}</div><p>Préparation collective accumulée : ${state.support}. Les lettres de classe ne changent que lorsqu’un groupe en dépasse un autre.</p>`);}
function showExamRules(){if(state.exam)return showResults();openModal(`${modalHead('EXAMEN SPÉCIAL · VENDREDI','Le contrat de confiance.','Un dossier, deux élèves et une promesse à tenir.')}<div class="rules-score"><div><b>50</b><small>Exactitude<br>Compétence et révision</small></div><div><b>30</b><small>Présentation<br>Communication et calme</small></div><div><b>20</b><small>Engagements<br>Séances et confiance</small></div></div><ul class="rules-list"><li>Choisissez un partenaire avant vendredi.</li><li>Révisez à la bibliothèque pour préparer votre dossier.</li><li>Aidez les autres binômes en salle de classe pour améliorer la moyenne.</li><li>Un contrat de tutorat peut réserver 4 000 PP jusqu’à une nouvelle séance.</li><li>Vendredi, restituez votre dossier en salle D. Trois questions évaluent votre lecture des faits.</li></ul><div class="hint-box">Récompenses : 1er +80 PC · 2e +40 · 3e +10 · 4e −30.<br>Une égalité partage les récompenses des places occupées. Aucun élève n’est exclu.</div><div class="button-row"><button class="secondary-btn" id="exam-back">Revenir au jeu</button><button class="primary-btn" id="exam-travel">${state.day===5?'Rejoindre la salle D':'Rejoindre la bibliothèque'} →</button></div>`,'exam-panel');$('#exam-back').onclick=closeModal;$('#exam-travel').onclick=()=>enterScene(state.day===5?'classroom':'library');}
const questions=[
 {title:'Séparer fait et rumeur.',dossier:'Un message non signé affirme que la classe C a acheté les réponses. Vous n’avez ni document original, ni témoignage direct.',question:'Comment l’intégrer au dossier ?',answers:['Le présenter comme un fait établi.','Le noter comme une rumeur non vérifiée.','Accuser le représentant de la classe C.'],correct:1,explain:'Une source non vérifiée ne devient pas une preuve.'},
 {title:'Une contrainte, un choix.',dossier:'Votre partenaire est indisponible jeudi à 17 h. La séance peut avoir lieu à 16 h ou à 17 h. Vous êtes libres tous les deux à 16 h.',question:'Quelle proposition respecte vos engagements ?',answers:['Maintenir 17 h et attendre qu’il s’adapte.','Annuler la préparation sans en parler.','Confirmer ensemble une séance à 16 h.'],correct:2,explain:'Un engagement viable tient compte des contraintes connues.'},
 {title:'Comprendre le collectif.',dossier:'Deux binômes obtiennent 90 et 30. Une séance d’aide peut augmenter le second de 20 points ; perfectionner le premier lui apporte 5 points.',question:'Quelle action améliore le plus la moyenne ?',answers:['Aider le second binôme : moyenne +10.','Perfectionner le premier : moyenne +10.','Les deux options donnent le même résultat.'],correct:0,explain:'La moyenne passe de 60 à 70 en aidant le second binôme.'}
];
function showPresentation(){if(state.exam)return showResults();if(state.day!==5||state.scene!=='classroom'){toast('La restitution a lieu vendredi en salle de classe D.');return;}
 if(!state.partner){openModal(`${modalHead('UN DERNIER BINÔME','Vous pouvez encore participer.','Daichi accepte un binôme de rattrapage. Vous n’aurez plus de journée de préparation, mais vous pouvez présenter le dossier.')}<button class="primary-btn" id="fallback-partner">Accepter le binôme de rattrapage →</button>`);$('#fallback-partner').onclick=()=>{fallbackPartner(state);persist();showPresentation();};return;}
 state.examDraft??={answers:[],strategy:null};const step=state.examDraft.answers.length;
 if(step<3){const q=questions[step];openModal(`${modalHead(`RESTITUTION · DOSSIER ${step+1} / 3`,q.title)}<div class="hint-box">${esc(q.dossier)}</div><p>${esc(q.question)}</p><div class="menu-list">${q.answers.map((a,i)=>`<button class="secondary-btn" data-answer="${i}">${esc(a)} <span>${i+1}</span></button>`).join('')}</div><p class="about-line">Pas de limite de temps. Votre progression est sauvegardée.</p>`);$$('[data-answer]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.answer);state.examDraft.answers.push(answer);persist();toast(answer===q.correct?'Lecture juste. '+q.explain:'Point à revoir. '+q.explain);showPresentation();});}
 else{const correct=state.examDraft.answers.filter((a,i)=>a===questions[i].correct).length;openModal(`${modalHead('RESTITUTION · DÉCISION FINALE','Comment conclure ?','Votre dossier est prêt. Choisissez l’accent de votre présentation.')}<div class="hint-box">Lecture des faits : ${correct} / 3 réponses justes.<br>Partenaire : ${esc(PEOPLE[state.partner].short)} · Préparation : ${state.prep} · Aide à la classe : ${state.support}</div><div class="menu-list"><button class="secondary-btn" data-strategy="balanced">Une présentation équilibrée <span>→</span></button><button class="secondary-btn" data-strategy="solo">Mettre notre binôme en avant <span>→</span></button><button class="primary-btn" data-strategy="team">Défendre le travail collectif <span>→</span></button></div><p class="about-line">Le calcul combine votre préparation, les capacités de votre partenaire, vos engagements et vos réponses. Le résultat est définitif pour cette partie.</p>`);$$('[data-strategy]').forEach(b=>b.onclick=()=>{const r=resolveExam(state,b.dataset.strategy);if(r.ok){persist();audio.chime();world.feedback('success','EXAMEN TERMINÉ');showResults();}else toast(r.message);});}
}
function showResults(){const e=state.exam;if(!e)return showExamRules();openModal(`${modalHead('RÉSULTATS OFFICIELS','Ce que nous avons accompli.')}<div class="results-two"><div><span class="eyebrow">VOTRE BINÔME · ${esc(PEOPLE[state.partner].short.toUpperCase())}</span><div class="result-score">${e.score}<small> / 100</small></div><p>Exactitude ${e.exact}/50 · Présentation ${e.oral}/30<br>Engagements ${e.commitments}/20${Number.isFinite(e.reading)?`<br>Lecture du dossier : ${e.reading}/3`:''}</p><span class="tag green">${e.score>=70?'Un dossier solide':'Une expérience à comprendre'}</span></div><div><span class="eyebrow">CLASSEMENT DE L’EXAMEN</span><table class="rank-table"><tbody>${e.ranking.map((r,i)=>`<tr class="${r.id==='d'?'you':''}"><td>0${e.ranking.filter(other=>other.score>r.score).length+1}${e.ranking.filter(other=>other.score===r.score).length>1?' =':''}</td><td>${esc(r.name)}</td><td>${r.score}/100</td></tr>`).join('')}</tbody></table></div></div><div class="hint-box">Classe D : <b>${e.reward>0?'+':''}${e.reward} PC</b>. Total : ${fmt(state.pc)} PC.<br>${e.strategy==='team'?'Vous avez défendu le travail du groupe. Reina et Mika s’en souviendront.':e.strategy==='solo'?'Vous avez valorisé votre binôme. Le collectif a reçu moins de soutien.':'Vous avez cherché un équilibre entre votre dossier et celui de la classe.'}</div><button class="primary-btn" id="results-return">Retrouver le campus →</button>`,'wide');$('#results-return').onclick=closeModal;}
function confirmSleep(){if(!canUseBed(state)){toast('Rejoignez votre lit dans la chambre 106.');return;}if(state.ended)return showSummary();if(state.day===5&&!state.exam){toast('Présentez le dossier en salle de classe avant de terminer vendredi.');return;}
 openModal(`${modalHead('VOTRE CHAMBRE',state.day===7?'Terminer cette première semaine ?':'Laisser la journée derrière soi.',state.day===7?'Les points, les engagements et les rencontres composent votre premier bilan.':`Il vous reste ${state.actions} créneau${state.actions>1?'x':''}. Dormir restaure votre énergie et réduit votre stress.`)}<div class="hint-box">${state.day===4?'Demain, les inscriptions seront closes. La restitution vous attend en classe D.':state.day===7?'Vous pourrez continuer à explorer après le bilan, ou recommencer avec une autre approche.':'Votre progression sera sauvegardée automatiquement.'}</div><div class="button-row"><button class="secondary-btn" id="sleep-cancel">Rester encore un peu</button><button class="primary-btn" id="sleep-confirm">${state.day===7?'Voir mon bilan':'Dormir jusqu’à demain'} →</button></div>`);$('#sleep-cancel').onclick=closeModal;$('#sleep-confirm').onclick=()=>{const r=nextDay(state);if(!r.ok){toast(r.message);return;}persist();closeModal();if(state.ended){showSummary();return;}world.setScene();transitioning=true;block();$('#day-transition h2').textContent=DAYS[state.day-1];$('#day-transition .transition-seal').textContent=['月','火','水','木','金','土','日'][state.day-1];const rp=r.report,fails=(r.requests??[]).filter(x=>x.status==='failed').length;$('#transition-report').innerHTML=rp?`Rapport de conduite, ${DAYS[rp.day-1].toLowerCase()}<b class="${rp.delta<0?'loss':rp.delta>0?'gain':''}">${rp.delta>0?'+':''}${rp.delta} PC</b>${state.conductKnown?`Conduite ${rp.label.toLowerCase()} (${rp.conduct}/100)`:'Motif non communiqué'}${fails?`<br>${fails} demande${fails>1?'s':''} non tenue${fails>1?'s':''}`:''}`:fails?`${fails} demande${fails>1?'s':''} non tenue${fails>1?'s':''}`:'';$('#day-transition p').textContent=`Avril · Jour ${state.day} · ${state.day===5?'Le jour de l’examen':'Un nouveau départ'}`;$('#toast').classList.remove('show');$('#day-transition').hidden=false;setTimeout(()=>{$('#day-transition').hidden=true;transitioning=false;block();},rp||fails?2600:1650);};}
function showSummary(){openModal(`${modalHead('PREMIÈRE SEMAINE · ÉPILOGUE','Une place à construire.',`${state.name}, votre première semaine a laissé des traces.`)}<div class="stats-grid"><div class="stat-card"><small>Points de classe</small><b>${fmt(state.pc)}</b></div><div class="stat-card"><small>Votre dossier</small><b>${state.exam?state.exam.score+'/100':'À présenter'}</b></div></div><p>${state.partner?`Vous avez fait équipe avec ${PEOPLE[state.partner].name}. `:''}${state.support>=14?'Vous avez choisi de soutenir la classe, même quand cela vous coûtait du temps.':state.prep>=24?'Vous avez construit votre réussite par une préparation méthodique.':'Vous avez commencé à découvrir les règles et ceux qui vivent avec elles.'}</p><div class="hint-box">${state.contract?.status==='fulfilled'?'Une promesse tenue vous lie à votre partenaire.':state.contract?.status==='expired'?'Une promesse manquée restera à réparer.':'Vos alliances se sont construites au fil des échanges.'}<br>Meilleure confiance : ${esc(PEOPLE[Object.entries(state.relationships).sort((a,b)=>b[1].trust-a[1].trust)[0][0]].short)}.<br>Réputation : ${esc(repTitle(state))} · ${state.requests.filter(q=>q.status==='done').length} demande(s) tenue(s) · conduite ${state.conductLog.reduce((t,e)=>t+e.delta,0)} PC sur la semaine.</div><p>Cette démo s’achève ici. Le campus reste ouvert à l’exploration. Une autre approche peut donner une autre semaine.</p><div class="button-row"><button class="secondary-btn" id="summary-explore">Continuer à explorer</button><button class="primary-btn" id="summary-restart">Nouvelle partie</button></div>`);$('#summary-explore').onclick=closeModal;$('#summary-restart').onclick=newGame;}
const REQUEST_LABELS={offered:'Nouvelle',active:'En cours',pending:'Remboursement attendu',done:'Accomplie',failed:'Échouée',declined:'Déclinée',expired:'Expirée'};
function requestsHtml(filter='all'){
 const order=['offered','active','pending','failed','done','declined','expired'],list=[...state.requests].filter(q=>filter==='all'||filter==='new'&&q.status==='offered'||filter==='active'&&['active','pending'].includes(q.status)||filter==='archive'&&['failed','done','declined','expired'].includes(q.status)).sort((a,b)=>order.indexOf(a.status)-order.indexOf(b.status));
 if(!list.length)return`<div class="suite-empty">${icon('user')}<h3>Rien en attente ici.</h3><p>Les demandes de vos camarades apparaîtront au fil de la semaine.</p></div>`;
 return`<div class="request-list">${list.map(q=>{const r=REQUESTS[q.id],p=PEOPLE[r.giver];return`<article class="request-card ${q.status}"><div class="request-person">${avatar(r.giver)}<div><b>${esc(p.short)}</b><small>${esc(p.role)}</small></div><span class="request-status">${REQUEST_LABELS[q.status]}</span></div><div class="request-copy"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><div class="request-goal">${icon('target')}${esc(r.goalText)}</div></div><footer><div><time>Jusqu’à ${esc(DAYS[r.until-1].toLowerCase())}</time><span class="reward">${esc(r.rewardText)}</span></div>${q.status==='offered'?`<div class="request-decisions"><button class="secondary-btn" data-req-decline="${q.id}">Décliner</button><button class="primary-btn" data-req-accept="${q.id}">Accepter ↗</button></div>`:''}</footer></article>`;}).join('')}</div>`;
}
function showRequests(filter='all'){
 openModal(`${modalHead('LA CLASSE COMPTE SUR VOUS','Entre camarades','Les petites promesses font les grandes alliances.')}<div class="tabs request-filters">${[['all','Tout'],['new','Nouvelles'],['active','En cours'],['archive','Archives']].map(([id,label])=>`<button class="tab-btn ${filter===id?'active':''}" data-request-filter="${id}">${label}${id==='new'?`<span>${state.requests.filter(q=>q.status==='offered').length}</span>`:''}</button>`).join('')}</div>${requestsHtml(filter)}<p class="about-line">Tenir une demande améliore votre fiabilité. Refuser ne coûte rien.</p>`,'requests-board');
 $$('[data-request-filter]').forEach(b=>b.onclick=()=>showRequests(b.dataset.requestFilter));$$('[data-req-accept]').forEach(b=>b.onclick=()=>{const r=acceptRequest(state,b.dataset.reqAccept);persist();toast(r.message);showRequests(filter);});$$('[data-req-decline]').forEach(b=>b.onclick=()=>{const r=declineRequest(state,b.dataset.reqDecline);persist();toast(r.message);showRequests(filter);});
}
function showShop(category='all'){
 const rows=Object.entries(ITEMS).filter(([id])=>category==='all'||ITEM_CATEGORIES[id]===category).map(([id,it],i)=>{const n=state.inventory[id],full=n>=it.max,late=id==='kit'&&state.exam;return`<article class="shop-item"><header><span>${ITEM_LABELS[id]}</span><small>${String(Object.keys(ITEMS).indexOf(id)+1).padStart(2,'0')}</small></header><div class="shop-art ${id}">${itemArt(id)}<span class="item-stock">${n}/${it.max} dans le sac</span></div><div class="shop-copy"><h3>${esc(it.name)}</h3><p>${esc(it.detail)}</p></div><footer><b>${fmt(it.price)}<small>PP</small></b><button class="primary-btn" data-buy="${id}" ${full||late||state.pp<it.price?'disabled':''}>${full?'Sac plein':late?'Indisponible':state.pp<it.price?'Solde insuffisant':'Acheter +'}<span class="sr-only"> ${esc(it.name)}</span></button></footer></article>`;}).join('');
 openModal(`<header class="modal-head shop-brand"><span class="eyebrow">GALERIE COMMERCIALE / ANHS</span><h2><svg viewBox="0 0 40 40" aria-hidden="true"><g fill="#d998a7">${[0,72,144,216,288].map(a=>`<path transform="rotate(${a} 20 20)" d="M20 20C10 13 11 4 16 4l4 4 4-4c5 0 6 9-4 16Z"/>`).join('')}</g><circle cx="20" cy="20" r="3" fill="#f0d7db"/></svg><span>Sakura<em>.</em></span><small>SUPÉRETTE<br>DU CAMPUS</small></h2><p>Un peu d’énergie pour la suite. Une attention pour quelqu’un.</p></header><div class="shop-toolbar"><div class="tabs shop-tabs">${[['all','Tout'],['consumables','Boissons'],['study','Études'],['gifts','Cadeaux']].map(([id,l])=>`<button class="tab-btn ${category===id?'active':''}" data-shop-category="${id}">${l}</button>`).join('')}</div><span class="shop-balance">${icon('shop')}<span>Votre solde<b>${fmt(state.pp)} <small>PP</small></b></span></span></div><div class="shop-grid">${rows}</div><div class="shop-note">${icon('clock')}<span>Les achats ne consomment aucun créneau.<small>Le dorayaki s’offre en conversation. Le kit agit automatiquement à l’examen.</small></span></div>`,'shop-menu');
 $$('[data-shop-category]').forEach(b=>b.onclick=()=>showShop(b.dataset.shopCategory));$$('[data-buy]').forEach(b=>b.onclick=()=>{const r=buyItem(state,b.dataset.buy);if(r.ok){persist();audio.tick();}toast(r.message);showShop(category);});
}
function showConduct(){const log=[...state.conductLog].reverse();
 if(!state.conductKnown){openModal(`${modalHead('RÈGLE INCONNUE','Conduite de la classe','Les points de la classe D bougent chaque soir de cours. Personne ne vous a dit pourquoi.')}${log.length?`<div class="conduct-history">${log.map(e=>`<div>${DAYS[e.day-1]}<b class="${e.delta<0?'loss':e.delta>0?'gain':''}">${e.delta>0?'+':''}${e.delta}</b>PC</div>`).join('')}</div>`:''}<div class="hint-box">Deux pistes : demander à Mme Hayase, en classe D, ou observer la cour centrale à partir de mardi.</div>`);return;}
 const [,delta,label]=conductStep(state.conduct);
 openModal(`${modalHead('RÈGLE DÉCOUVERTE','Conduite de la classe',`Conduite actuelle : ${Math.round(state.conduct)} / 100, ${label.toLowerCase()}.`)}<div class="rules-score"><div><b>+5</b><small>70 et plus<br>Exemplaire</small></div><div><b>0</b><small>55 à 69<br>Correcte</small></div><div><b>−10</b><small>40 à 54<br>Relâchée</small></div><div><b>−20</b><small>Moins de 40<br>Préoccupante</small></div></div>${log.length?`<span class="small-section">RAPPORTS DE LA SEMAINE</span><div class="conduct-history">${log.map(e=>`<div>${DAYS[e.day-1]}<b class="${e.delta<0?'loss':e.delta>0?'gain':''}">${e.delta>0?'+':''}${e.delta}</b>${e.conduct}/100</div>`).join('')}</div>`:''}<ul class="rules-list"><li>Chaque soir de cours, l’école publie un rapport : ${state.day<=5&&!state.ended?`ce soir, ${delta>0?'+':''}${delta} PC si rien ne change.`:'plus de rapport cette semaine.'}</li><li>Sans effort, la conduite baisse de 7 points chaque jour.</li><li>Tutorat collectif : +6. Demande accomplie : +3. Rappel des règles avec Sora : +5, une fois par jour.</li></ul>`);}
function showRepHelp(){return`<div class="rep-detail">${REP_LABELS.map(([k,l,d])=>`<div><small>${l}</small><b>${state.rep[k]}</b><small>${d}</small></div>`).join('')}</div>`;}
function showPause(){openModal(`${modalHead('VOTRE SESSION','Une pause.',"Le campus sera encore là à votre retour.")}<div class="session-layout"><section class="session-story"><div class="session-story-art"></div><span class="session-chapter">CHAPITRE 01 / AVRIL</span><h3>Le contrat<br>de confiance.</h3><p>Sept jours. Une classe.<br>Une place à construire.</p><div class="session-progress"><span>JOUR</span><b>${String(state.day).padStart(2,'0')}<small> / 07</small></b><div>${DAYS.map((d,i)=>`<i class="${i+1<=state.day?'done':''}" title="${d}"></i>`).join('')}</div></div><button class="primary-btn" id="resume-game">Reprendre la partie <span>↗</span></button></section><div class="session-settings"><header class="section-heading"><h3>À votre rythme</h3><span>RÉGLAGES</span></header><div class="menu-list"><button class="secondary-btn" id="pause-sound">${icon('sound')}Ambiance sonore <span class="switch-label ${audio.enabled?'on':''}">${audio.enabled?'Activée':'Coupée'}</span></button><button class="secondary-btn" id="effects-mode">${icon('spark')}Effets visuels <span>${world.effectMode==='soft'?'Doux':'Complets'} ↔</span></button><button class="secondary-btn" id="fullscreen">${icon('expand')}Plein écran <span>⛶</span></button><button class="secondary-btn" data-pause="help">${icon('help')}Commandes <span>↗</span></button></div><header class="section-heading saves-heading"><h3>Garder sa progression</h3><span>SAUVEGARDE</span></header><div class="save-actions"><button class="secondary-btn" id="export-save">Exporter <span>↓</span></button><button class="secondary-btn" id="import-save">Importer <span>↑</span></button></div><p class="about-line">${storageAvailable?'Votre progression est conservée dans ce navigateur.':'Sauvegarde locale indisponible. Exportez votre partie pour la conserver.'}</p><button class="session-exit" id="to-title">Retour à l’écran titre <span>↗</span></button></div></div>`,'pause-menu');$('#resume-game').onclick=closeModal;$('#pause-sound').onclick=()=>{audio.toggle();showPause();};$('#effects-mode').onclick=()=>{world.setEffects(world.effectMode==='soft'?'full':'soft');showPause();};$$('[data-pause]').forEach(b=>b.onclick=()=>showMenu(b.dataset.pause));$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>toast('Plein écran indisponible.'));else $('#game').requestFullscreen?.().catch(()=>toast('Plein écran indisponible dans ce navigateur.'));};$('#export-save').onclick=exportSave;$('#import-save').onclick=importSave;$('#to-title').onclick=()=>{save();saved=structuredClone(state);$('#continue').hidden=false;closeModal();running=false;world.active=false;world.clearInput();$('#hud').hidden=true;$('#title-screen').hidden=false;$('#continue').focus();};}
function showHelp(){openModal(`${modalHead('AIDE / EXPLORATION','Commandes','Se déplacer et parler ne consomme aucun créneau.')}<div class="controls-list"><div><span>Marcher</span><span><kbd>ZQSD</kbd> <kbd>WASD</kbd> <kbd>↑↓←→</kbd></span></div><div><span>Courir</span><kbd>Maj + déplacement</kbd></div><div><span>Parler, entrer ou utiliser un objet</span><kbd>E</kbd></div><div><span>Marcher vers un endroit</span><span>Clic / toucher</span></div><div><span>Carte et déplacement rapide</span><kbd>M</kbd></div><div><span>Téléphone · Carnet · Profil</span><span><kbd>P</kbd> <kbd>J</kbd> <kbd>C</kbd></span></div><div><span>Masquer / afficher le HUD</span><kbd>H</kbd></div><div><span>Pause / fermer un menu</span><kbd>Échap</kbd></div><div><span>Choisir une réplique</span><kbd>1 à 5</kbd></div></div><div class="hint-box">Choisissez un partenaire avant vendredi. Révisez à la bibliothèque, aidez votre classe et tenez vos promesses. Pour passer au jour suivant, rejoignez le lit dans votre chambre.</div><p>Chaque journée offre trois créneaux. Le vendredi, présentez votre dossier en classe D. Sur mobile, utilisez les commandes tactiles et les icônes du téléphone et de la carte.</p><p class="about-line">Projet de fan, personnages et scénario originaux. Démo solo, sans multijoueur.</p>`);}
function exportSave(){save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='anhs-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde exportée.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files?.[0];if(!file||file.size>1000000)throw Error();const next=validateState(JSON.parse(await file.text()));if(!next)throw Error();openModal(`${modalHead('IMPORT DE SAUVEGARDE','Reprendre cette histoire ?',`${next.name} · ${DAYS[next.day-1]} · ${fmt(next.pp)} PP`)}<p>Cette partie remplacera la progression actuelle dans ce navigateur.</p><div class="button-row"><button class="secondary-btn" id="import-cancel">Annuler</button><button class="primary-btn" id="import-confirm">Importer</button></div>`);$('#import-cancel').onclick=showPause;$('#import-confirm').onclick=()=>{startGame(next);toast('Sauvegarde importée.');};}catch{toast('Ce fichier n’est pas une sauvegarde ANHS valide.');}};input.click();}
const audio={enabled:false,ctx:null,timer:null,volume:.13,step:0,notes:[196,246.94,293.66,392,440,293.66,246.94,220],
 toggle(){if(this.enabled){this.enabled=false;clearInterval(this.timer);this.ctx?.suspend();}else{try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume();this.enabled=true;this.tick();this.timer=setInterval(()=>this.tick(),1900);}catch{toast('Ambiance sonore indisponible.');}}if(running)updateHud();},
 note(freq,length=2.8,volume=.08){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume*this.volume,t+.12);g.gain.exponentialRampToValueAtTime(.0001,t+length);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+length+.1);},
 footstep(scene,running){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime,len=.065;const buffer=this.ctx.createBuffer(1,Math.ceil(this.ctx.sampleRate*len),this.ctx.sampleRate),data=buffer.getChannelData(0);let smooth=0;for(let i=0;i<data.length;i++){smooth=(smooth+(Math.random()*2-1)*.2)*.78;data[i]=smooth*(1-i/data.length);}const source=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),gain=this.ctx.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=['campus','courtyard'].includes(scene)?1400:700;gain.gain.setValueAtTime(this.volume*(running ? .55 : .38),t);gain.gain.exponentialRampToValueAtTime(.0001,t+len);source.connect(filter);filter.connect(gain);gain.connect(this.ctx.destination);source.start(t);},
 tick(){this.note(this.notes[this.step++%this.notes.length],3,.18);if(this.step%3===0)this.note(98,4,.13);},chime(){this.note(392,1.2,.2);setTimeout(()=>this.note(493.88,1.3,.2),140);setTimeout(()=>this.note(587.33,1.7,.18),290);}
};
world.onFootstep=({scene,running})=>audio.footstep(scene,running);
$('#sound').onclick=()=>audio.toggle();
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(e.target.matches('input,textarea,select')){if(key==='escape')closeModal();return;}if(key==='tab'&&(!$('#modal').hidden||!$('#dialogue').hidden)){const parent=$('#modal').hidden?$('#dialogue'):$('#modal');const focusables=[...parent.querySelectorAll('button:not(:disabled),input,[tabindex="0"]')];if(focusables.length){const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}
 if(key==='escape'){e.preventDefault();if(!$('#dialogue').hidden)closeDialogue();else if(!$('#modal').hidden)closeModal();else if(running)showPause();return;}
 if(!running||transitioning)return;
 if(!$('#dialogue').hidden){const n=Number(key);if(n>=1&&n<=6){e.preventDefault();chooseDialogue(n-1);}return;}
 if(!$('#modal').hidden){if(['arrowup','arrowdown'].includes(key)){e.preventDefault();const buttons=$$('#modal button:not(:disabled)').filter(b=>b.getClientRects().length),index=buttons.indexOf(document.activeElement),next=(index+(key==='arrowdown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus();}return;}
 if(['arrowleft','arrowright','arrowup','arrowdown','q','a','z','w','s','d','shift'].includes(key)){e.preventDefault();world.moveKey(key,true);return;}
 if(e.repeat)return;
 if(['1','2','3','4'].includes(key)){e.preventDefault();useBag(Number(key)-1);return;}if(key==='h'){e.preventDefault();$('#hud').hidden=!$('#hud').hidden;$('#world').focus();}else if(key==='e'){e.preventDefault();world.interact();}else if(key==='m')showMap();else if(key==='p')showPhone();else if(key==='j')showJournal();else if(key==='c')showProfile();
});
window.addEventListener('keyup',e=>world.moveKey(e.key.toLowerCase(),false));window.addEventListener('blur',()=>{world.clearInput();save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){world.clearInput();save();}});window.addEventListener('pagehide',save);
$('#world').addEventListener('pointerdown',e=>{if(e.button!==0||!running)return;const r=e.target.getBoundingClientRect();world.goToScreen(e.clientX-r.left,e.clientY-r.top);e.target.focus();});
